// Module registry for this client (blueprint section 7). Passed through to every
// downstream node; modules receive it as context.client_config.
const registry = {
  client: 'glamour-salon',
  channels: { whatsapp: true, messenger: true, instagram: true, email: false, web: true },
  sheets: { conversations: 'glamour_conversations', leads: 'glamour_leads', bookings: 'glamour_bookings' },
  modules: {
    rules: { enabled: true, workflow_id: 'E4OMq15MVN02rvMM', rules_file: 'glamour_rules.csv' },
    rag: { enabled: true, workflow_id: 'ZJ6BeDNECT4bYFFC', qdrant_collection: 'glamour_kb', threshold: 0.55, top_k: 3 },
    booking: {
      enabled: true, workflow_id: 'XIdIZ2lnp7ZZKQxW', calendar_id: 'primary',
      services: { Haircut: { duration_minutes: 60, price: 500 } },
      business_hours: { open: '10:00', close: '20:00', days: [1, 2, 3, 4, 5, 6], timezone: 'Asia/Dhaka' },
      templates: { confirm: 'booking_confirm', reminder: 'booking_reminder', recovery: 'booking_recovery', language: 'en_US' },
      slack_channel: 'bookings', reminder_lead_24h: 24, reminder_lead_2h: 2, no_show_grace_minutes: 30,
      max_reminder_attempts: 3, recovery_slot_count: 3, slot_step_minutes: 30, attendance_marker: '[ATTENDED]',
      dedupe_window_minutes: 10, booking_id_prefix: 'BK', location_text: 'Glamour Salon, Gulshan 2, Dhaka',
      client_name: 'Glamour Salon', phone_country_code: '880'
    },
    lead_capture: { enabled: true, workflow_id: 'G95nOwNXvstqOFoP' },
    support_triage: { enabled: false, workflow_id: 'ayDgfI4zsTn80Erq', slack_channel: 'support', sla_minutes: 60 },
    handoff: { enabled: true, workflow_id: 'bLSYgRzPGzwGju6i', team_phone: '+8801XXXXXXXXX' }
  },
  routing: { fallback: 'guided_prompt' },
  brand: { name: 'Glamour Salon', voice: 'Friendly, concise, Bangla or English matching the customer.', languages: ['bn', 'en'] },
  business_hours: { open: '10:00', close: '20:00', days: [1, 2, 3, 4, 5, 6], timezone: 'Asia/Dhaka' }
};
return [{ json: { ...$json, ...registry } }];

// Normalize every channel payload into the canonical message object (blueprint section 5).
const item = $input.first().json;
const body = (item.body && typeof item.body === 'object') ? item.body : item;
const registry = $('Registry').first().json;
const tz = registry.business_hours.timezone;
const channel = item.channel || '';
// Messenger and Instagram timestamps are epoch milliseconds; WhatsApp uses seconds.
const toIso = (epoch) => {
  if (!epoch) return DateTime.now().setZone(tz).toISO();
  const n = Number(epoch);
  return DateTime.fromMillis(n >= 1e12 ? n : n * 1000, { zone: tz }).toISO();
};
const out = {
  channel: 'web', thread_id: '', provider_message_id: '',
  sender: { name: '', id: '', phone: '' }, text: '', attachments: [],
  timestamp: DateTime.now().setZone(tz).toISO(), raw: body
};
// Meta trio (t01 to t03): entry[0].changes[0].value
const value = body.entry && body.entry[0] && body.entry[0].changes &&
  body.entry[0].changes[0] && body.entry[0].changes[0].value;
// Meta status updates (delivery receipts, read receipts) carry no customer message; ignore them.
if (value && value.statuses && !(value.messages && value.messages.length)) {
  return [];
}
if (value && value.messages && value.messages[0]) {
  const msg = value.messages[0];
  const contacts = value.contacts || [];
  const profile = contacts[0] && contacts[0].profile ? contacts[0].profile : {};
  out.channel = 'whatsapp';
  out.thread_id = String(msg.from || '');
  out.provider_message_id = String(msg.id || msg.wamid || '');
  out.sender = { name: profile.name || '', id: String(msg.from || ''), phone: String(msg.from || '') };
  // Interactive button replies carry no text.body; flatten the button id (or
  // title) into text so downstream SLOT_ detection keeps working.
  const buttonReply = msg.interactive && msg.interactive.button_reply ? msg.interactive.button_reply : null;
  out.text = buttonReply ? String(buttonReply.id || buttonReply.title || '') : ((msg.text && msg.text.body) ? String(msg.text.body) : '');
  out.timestamp = toIso(msg.timestamp);
  return [{ json: out }];
}
// Messenger + Instagram (t02/t03): real envelopes deliver entry[].messaging[]
// directly, discriminated by the webhook object field (#41; page -> messenger,
// instagram -> instagram). Page-sent echoes and delivery/read receipts carry
// no customer message and are dropped so they cannot self-loop the reply path.
if (body.object && body.entry && body.entry[0] && body.entry[0].messaging && body.entry[0].messaging[0]) {
  const m = body.entry[0].messaging[0];
  if (!m.message || m.message.is_echo) {
    return [];
  }
  const sender = m.sender || {};
  out.channel = body.object === 'instagram' ? 'instagram' : 'messenger';
  out.thread_id = String(sender.id || '');
  out.provider_message_id = String(m.message.mid || '');
  out.sender = { name: '', id: String(sender.id || ''), phone: '' };
  out.text = m.message.text ? String(m.message.text) : '';
  out.attachments = Array.isArray(m.message.attachments)
    ? m.message.attachments.map(a => ({ type: String(a.type || ''), url: a.payload ? String(a.payload.url || '') : '' }))
    : [];
  out.timestamp = toIso(m.timestamp);
  return [{ json: out }];
}
// Email (t04): IMAP item with subject, from, messageId, date
if (item.subject !== undefined || item.from !== undefined) {
  const from = String(item.from || '');
  out.channel = 'email';
  out.thread_id = from.toLowerCase() + ':' + String(item.messageId || '');
  out.provider_message_id = String(item.messageId || '');
  out.sender = { name: String(item.fromName || ''), id: from, phone: '' };
  out.text = String(item.subject || '') + (item.text ? '\n' + item.text : '');
  out.timestamp = item.date ? DateTime.fromISO(new Date(item.date).toISOString(), { zone: tz }).toISO() : DateTime.now().setZone(tz).toISO();
  return [{ json: out }];
}
// Web widget (t05): canonical JSON body { session_id, text, name, timestamp }
if (body.session_id || body.text !== undefined) {
  out.channel = 'web';
  out.thread_id = String(body.session_id || '');
  out.provider_message_id = String(body.session_id || '') + ':' + String(body.message_counter || 0);
  out.sender = { name: String(body.name || ''), id: String(body.session_id || ''), phone: '' };
  out.text = String(body.text || '');
  out.attachments = body.attachments || [];
  out.timestamp = body.timestamp || DateTime.now().setZone(tz).toISO();
  return [{ json: out }];
}
// Unknown envelope (#41): drop it instead of emitting an empty web canonical
// that masquerades as real traffic. Observable as an empty Normalize output.
return [];

// Dedupe on provider_message_id using a rolling window in n8n static data (last 1000 ids).
// Single output: emits _oc_dedupe = 'unique' | 'duplicate'; the "Dedupe unique?" IF node
// does the branching (multi-output Code nodes are not supported on current n8n).
const msg = $input.first().json;
const key = String(msg.provider_message_id || '');
const windowKey = 'omni_dedupe_window';
let seen = $getWorkflowStaticData('global')[windowKey] || [];
let branch = 'unique';
if (key && seen.includes(key)) {
  branch = 'duplicate';
} else if (key) {
  seen.push(key);
  if (seen.length > 1000) seen = seen.slice(-1000);
  $getWorkflowStaticData('global')[windowKey] = seen;
}
return [{ json: { ...msg, _oc_dedupe: branch } }];

// Wrap the canonical message into the module input contract (blueprint section 6.1).
// Internal _oc_* routing flags are stripped here so they never cross the module boundary.
const raw = $input.first().json;
const msg = {};
for (const k of Object.keys(raw)) {
  if (!k.startsWith('_oc_')) msg[k] = raw[k];
}
const registry = $('Registry').first().json;
return [{
  json: {
    message: msg,
    context: {
      thread_state: {},
      client_config: registry,
      history_tail: [],
      meta: { execution_id: $execution.id, attempt: 1 }
    }
  }
}];

// Rules engine gate (blueprint section 11 step 1). Ports the M1 matcher semantics
// verbatim onto the CSV rows read by Read rules CSV and Extract rules CSV. Single
// output: emits _oc_rules_route = 'matched' | 'rag' | 'llm'; the "Rules matched?" and
// "RAG enabled?" IF nodes do the branching (intent rules vs other, embedding skipped
// entirely when RAG is disabled). Multi-output Code nodes are unsupported on current n8n.
const MAX_TEXT = 500;
const registry = $('Registry').first().json;
const rulesCfg = registry.modules.rules;
const wrapped = $('Wrap module input').first().json;
const message = wrapped.message;
// File nodes replace items and failed file nodes emit error items; keep only
// real rule rows.
const rows = $input.all().map(function (item) { return item.json; })
  .filter(function (row) { return typeof row.pattern === 'string'; });

// Normalize rules. Priority ascending, lower number wins; ties keep CSV order.
function normalizeRules(rows) {
  return rows.map(function (row) {
    const rawPriority = String(row.priority ?? '').trim();
    return {
      pattern: String(row.pattern ?? '').trim(),
      reply: String(row.reply ?? ''),
      channel: String(row.channel ?? '').trim().toLowerCase() || 'all',
      priority: rawPriority !== '' && Number.isFinite(Number(rawPriority)) ? Number(rawPriority) : 100
    };
  }).sort(function (a, b) { return a.priority - b.priority; });
}

// Channel filter: all or empty matches every channel, else a comma separated list.
function channelOk(ruleChannel, msgChannel) {
  if (!ruleChannel || ruleChannel === 'all') return true;
  return ruleChannel.split(',').map(function (c) { return c.trim(); }).includes(msgChannel);
}

// A quantified group that itself contains a quantifier or an alternation, for
// example (a+)+ or (a|aa)+, can backtrack catastrophically on attacker
// controlled text. Such patterns skip the regex engine and use the substring
// check instead.
function patternIsRisky(pattern) {
  return /\([^()]*[+*?|][^()]*\)\s*[+*{]/.test(pattern);
}

// Pattern match: regex with the i flag; an invalid or risky regex falls back to
// a case-insensitive substring check so a plain text pattern still works. The
// text is capped before matching to bound regex work on long messages.
function textMatches(pattern, text) {
  try {
    if (!patternIsRisky(pattern)) {
      return new RegExp(pattern, 'i').test(text);
    }
  } catch (e) {
    // invalid regex, fall through to the substring check
  }
  return text.toLowerCase().includes(pattern.toLowerCase());
}

let matched = null;
if (rulesCfg.enabled && rows.length) {
  const rules = normalizeRules(rows);
  const text = String(message.text || '').slice(0, MAX_TEXT);
  for (const rule of rules) {
    if (!rule.pattern) continue;
    if (!channelOk(rule.channel, message.channel)) continue;
    if (textMatches(rule.pattern, text)) { matched = rule; break; }
  }
}
if (matched) {
  return [{ json: { ...wrapped, intent: 'rules', _oc_rules_route: 'matched' } }];
}
if (registry.modules.rag.enabled) {
  return [{ json: { ...wrapped, intent: 'other', _oc_rules_route: 'rag' } }];
}
return [{ json: { ...wrapped, intent: 'other', _oc_rules_route: 'llm' } }];

// RAG confidence gate (blueprint section 11 step 2). Qdrant POST /points/query returns
// { result: { points: [{ id, score, payload }] } }; read scores from result.points.
// Single output: emits _oc_rag_route = 'answer' | 'low'; the "RAG above threshold?"
// IF node does the branching (multi-output Code nodes are unsupported on current n8n).
const registry = $('Registry').first().json;
const threshold = registry.modules.rag.threshold;
const points = ($json.result && $json.result.points) || [];
const best = points.length ? points[0].score : 0;
const msg = $('Wrap module input').first().json.message;
const ctx = $('Wrap module input').first().json.context;
if (best >= threshold) {
  return [{ json: { ...$json, message: msg, context: ctx, intent: 'rag', rag_score: best, _oc_rag_route: 'answer' } }];
}
return [{ json: { ...$json, message: msg, context: ctx, intent: 'other', rag_score: best, _oc_rag_route: 'low' } }];

// Parse the strict JSON intent result (blueprint section 11 step 3). #40
// hardening: LLM classify degrades with onError continueRegularOutput +
// alwaysOutputData, so a failed call arrives here as an error item. Emit a
// clean contract item with intent other (no Route rule matches it) so it
// rides Route's fallbackOutput into Resolve fallback instead of dying.
// Sandbox models wrap JSON in markdown fences or truncate leading braces
// (freellmapi does not honor response_format), so strip fences and fall back
// to the first {...} block before giving up.
const raw = $json;
const content = raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content;
let parsed = {};
if (!raw.error && content) {
  let text = String(content).trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) text = fence[1].trim();
  try { parsed = JSON.parse(text); } catch (e) {
    const brace = text.match(/\{[\s\S]*\}/);
    if (brace) { try { parsed = JSON.parse(brace[0]); } catch (e2) { parsed = {}; } }
  }
}
const failed = Boolean(raw.error) || !content;
const intent = ['booking', 'lead', 'support', 'handoff', 'other'].includes(parsed.intent) ? parsed.intent : 'other';
const src = $('Wrap module input').first().json;
return [{ json: { message: src.message, context: src.context, intent, language: parsed.language || 'en', confidence: parsed.confidence || 0, _oc_classify: failed ? 'fail' : 'ok' } }];

// Guided prompt fallback (blueprint section 4 n27).
const msg = $('Wrap module input').first().json.message;
return [{ json: { reply: { channel: msg.channel, type: 'text', text: 'What can I help you with? For example, booking, prices or support.' }, message: msg } }];

// Attach the canonical message to the module output so the reply router, log and
// state persist nodes can read the sender and thread id (blueprint section 6.4).
const msg = $('Wrap module input').first().json.message;
return [{ json: { ...$json, message: msg } }];

// Module failure fallback reply (blueprint section 4 n12).
const msg = $('Wrap module input').first().json.message;
return [{ json: { reply: { channel: msg.channel, type: 'text', text: 'One moment, I am checking that for you.' }, message: msg } }];

// Prepare inbound and outbound log rows for the conversation log (blueprint section 10).
// Read from the reply router (Send reply) because httpRequest send nodes replace the
// item with the HTTP response body and do not pass the module output through.
// Send reply is a multi-output switch; $() defaults to output 0, which is empty on
// non-WhatsApp branches, so scan every slot for the first non-empty one (#40 follow-up).
const sr = $('Send reply');
let src = null;
for (let i = 0; i < 8; i++) {
  let batch = [];
  try { batch = sr.all(i); } catch (e) { break; }
  if (batch && batch.length) { src = batch[batch.length - 1].json; break; }
}
if (!src) { return []; }
const msg = src.message;
const reply = src.reply;
const state = src.state;
const now = new Date().toISOString();
const rows = [];
if (msg) {
  rows.push({ thread_id: msg.thread_id, channel: msg.channel, direction: 'inbound', text: msg.text, module: '', state: '', timestamp: msg.timestamp || now });
}
if (reply) {
  rows.push({ thread_id: msg ? msg.thread_id : '', channel: reply.channel, direction: 'outbound', text: reply.text, module: '', state: JSON.stringify(state || {}), timestamp: now });
}
return rows.map(r => ({ json: r }));

// Human ownership gate (blueprint section 9). The Sheets read above returns every
// conversation row for this thread; append order is chronological. alwaysOutputData
// on the read node emits one empty item when the thread has no rows yet, so rows
// without a string thread_id are dropped first. With onError continueRegularOutput
// on the read node a Sheets outage degrades the same way: thread treated as free.
// Single output: emits _oc_human_free = 'yes' | 'no'; the "Thread human free?" IF
// node does the branching (multi-output Code nodes are unsupported on current n8n).
const rows = $input.all().filter(function (item) {
  return item.json && typeof item.json.thread_id === 'string' && !item.json.error;
});
const msg = $('Dedupe').first().json;
if (!rows.length) {
  return [{ json: { ...msg, _oc_human_free: 'yes' } }];  // no state yet, continue
}
// Backward scan: use the newest row that actually carries a non-empty state value,
// so a dropped reply or an empty-state newest row cannot hide human_owned set earlier.
let parsed = {};
for (let i = rows.length - 1; i >= 0; i--) {
  const raw = String(rows[i].json.state ?? '').trim();
  if (!raw) continue;
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  break;
}
if (parsed.human_owned === true) {
  return [{ json: { ...msg, _oc_human_free: 'no' } }];  // human owned, silent exit until reset
}
return [{ json: { ...msg, _oc_human_free: 'yes' } }];  // continue

// Dispatch layer (plan step 7, refactored step 8). Strips every routing-only field so
// the module receives exactly the section 6.1 contract input. Enable/disable routing
// lives in the "Mx enabled?" IF node reading the Registry directly (multi-output Code
// nodes are unsupported on current n8n).
return [{ json: { message: $json.message, context: $json.context } }];

