return [{ json: { message: $json.message, context: $json.context } }];

// Dispatch layer (plan step 7, refactored step 8). Strips every routing-only field so
// the module receives exactly the section 6.1 contract input. Enable/disable routing
// lives in the "Mx enabled?" IF node reading the Registry directly (multi-output Code
// nodes are unsupported on current n8n).
return [{ json: { message: $json.message, context: $json.context } }];

// Dispatch layer (plan step 7, refactored step 8). Strips every routing-only field so
// the module receives exactly the section 6.1 contract input. Enable/disable routing
// lives in the "Mx enabled?" IF node reading the Registry directly (multi-output Code
// nodes are unsupported on current n8n).
return [{ json: { message: $json.message, context: $json.context } }];

// Dispatch layer (plan step 7, refactored step 8). Strips every routing-only field so
// the module receives exactly the section 6.1 contract input. Enable/disable routing
// lives in the "Mx enabled?" IF node reading the Registry directly (multi-output Code
// nodes are unsupported on current n8n).
return [{ json: { message: $json.message, context: $json.context } }];

// Resolve fallback policy (plan step 7; #44 refactor). Single output with a
// _oc_fallback discriminator; the Fallback handoff? IF gate routes it
// (guided -> Guided prompt, handoff -> Execute M6 Handoff while the handoff
// module is enabled). Multi-output Code nodes fail at runtime on n8n
// 2.34.5 (BUGS #44), so this node must stay single-output.
const reg = $('Registry').first().json;
const mode = (reg.routing && reg.routing.fallback) || 'guided_prompt';
const handoffOk = mode === 'handoff' && Boolean((reg.modules.handoff || {}).enabled);
return $input.all().map(function (item) {
  return { json: { message: item.json.message, context: item.json.context, _oc_fallback: handoffOk ? 'handoff' : 'guided' } };
});
